def criar_obrigacoes_existentes(apps, schema_editor):
    Pedido = apps.get_model("sales", "Pedido")
    ItemPedido = apps.get_model("sales", "ItemPedido")
    Reserva = apps.get_model("stock", "ReservaEstoque")
    Obrigacao = apps.get_model("sales", "ObrigacaoEstoquePedido")

    status_pagos = {
        "pago",
        "em_separacao",
        "pronto_para_entrega",
        "enviado",
        "concluido",
    }
    status_cancelados = {"cancelado", "falhou"}

    for pedido in Pedido.objects.all().iterator():
        agregados = (
            ItemPedido.objects.filter(pedido_id=pedido.pk)
            .values("produto_id")
            .annotate(total=Sum("quantidade"))
        )
        for linha in agregados:
            devida = Decimal(linha["total"] or "0.00")
            if devida <= 0:
                continue
            consumidas = Reserva.objects.filter(
                pedido_id=pedido.pk,
                produto_id=linha["produto_id"],
                unidade_id=pedido.unidade_id,
                status="consumida",
            ).aggregate(total=Sum("quantidade"))["total"] or Decimal("0.00")
            if (
                pedido.status_financeiro == "pago"
                and pedido.status in status_pagos
            ):
                baixada = devida
                status = "resolvida"
            elif (
                pedido.status in status_cancelados
                or pedido.status_financeiro in ("cancelado", "estornado")
            ):
                baixada = min(consumidas, devida)
                status = "cancelada"
            else:
                baixada = min(consumidas, devida)
                status = "resolvida" if baixada >= devida else "pendente"
            Obrigacao.objects.create(
                pedido_id=pedido.pk,
                produto_id=linha["produto_id"],
                unidade_id=pedido.unidade_id,
                quantidade_devida=devida,
                quantidade_baixada=baixada,
                status=status,
                motivo_pendencia=(
                    ""
                    if status == "resolvida"
                    else "obrigação criada na migração de estoque"
                ),
            )


